/* Publishing credentials stay in server memory, never in browser storage. */
const publishPanel=document.createElement('section');publishPanel.className='publishing-panel';publishPanel.innerHTML=`
<h2>Automatically post your clips</h2><p>Finished edits → TikTok + YouTube Shorts. Connect your accounts and choose where each finished clip goes.</p>
<p id="publishState" role="status">Checking publishing connection…</p>
<div class="account-signin"><p>Sign in securely, return here, then enable automatic posting. Your passwords stay with TikTok and Google.</p><button id="signInTikTok" type="button" class="primary">Connect TikTok</button> <button id="signInYouTube" type="button" class="primary">Connect YouTube</button> <button id="refreshAccounts" type="button">I’ve connected my accounts</button><p id="signInSetup" role="status"></p></div>
<form id="publisherSettings" hidden><label for="publisherProfile">Post to these accounts</label><select id="publisherProfile" required></select><p id="publisherAccounts"></p>
<label for="publisherVisibility">Who can see these posts?</label><select id="publisherVisibility" required><option value="">Choose visibility</option><option value="public">Public on both platforms</option><option value="private">Private on both platforms</option></select>
<label for="publisherAudience">Are these videos made for children?</label><select id="publisherAudience" required><option value="">Choose YouTube audience</option><option value="no">No, not made for children</option><option value="yes">Yes, made for children</option></select>
<label for="publisherCaption">Caption template</label><textarea id="publisherCaption" maxlength="1500">{title}</textarea><p>Use {title} for each clip’s title and {part} for its part number. YouTube titles use the clip title; this text becomes its description.</p>
<label><input type="checkbox" id="publisherSynthetic"> Contains realistic AI-generated or altered content</label><label><input type="checkbox" id="publisherOwnBrand"> Promotes my own brand</label><label><input type="checkbox" id="publisherPaidBrand"> Paid partnership / promotes another brand</label>
<label><input type="checkbox" id="publisherConsent" required> Automatically send every newly rendered clip to the accounts above using these settings. I have the rights to publish it and agree to <a href="https://www.tiktok.com/legal/page/global/music-usage-confirmation/en" target="_blank" rel="noopener">TikTok’s Music Usage Confirmation</a> and, for paid partnerships, its <a href="https://www.tiktok.com/legal/page/global/bc-policy/en" target="_blank" rel="noopener">Branded Content Policy</a>.</label>
<p>Clips and captions are sent through Upload-Post. TikTok comments, Duet and Stitch are off. Both destinations receive clips independently; limits or rejections are shown below. Keep the studio server running. Existing exports are not posted retroactively.</p>
<button type="submit" class="primary">Enable automatic posting to both</button></form>
<button id="publisherPause" hidden>Pause automatic posting</button><p id="publisherError" role="alert"></p><h3>Posting queue</h3><p>Rendering and posting are separate. “Published” appears only after a confirmed post link is returned. Pausing stops new uploads; already-submitted posts can still finish.</p><div id="publisherQueue">No posts queued.</div>`;
document.querySelector('.import-panel').after(publishPanel);
let publishSnapshot=null;
async function publishRequest(route,data){const res=await fetch('/api/publishing'+route,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const body=await res.json();if(!res.ok)throw Error(body.error||'Publishing request failed');return body}
function accountText(){const p=publishSnapshot?.profiles.find(p=>p.username===$('publisherProfile').value);$('publisherAccounts').textContent=p?['tiktok','youtube'].map(k=>k+': '+(p.accounts[k]?.name||'Not connected')).join(' · '):'Connect both accounts in one profile.'}
function drawPublishing(data){publishSnapshot=data;$('signInSetup').textContent=data.signInReady?'Account authorization opens in a secure new tab.':'Sign-in setup is incomplete: the publishing service must be configured on the server first. You do not need to paste a key here.';$('publishState').textContent=data.enabled?'Automatic posting ON — new renders will be sent to both accounts.':data.connected?'Accounts connected. Automatic posting is paused.':'Not connected — clips will only download until you finish setup.';$('publisherSettings').hidden=!data.connected;$('publisherPause').hidden=!data.enabled;
 const select=$('publisherProfile'),old=select.value;if(JSON.stringify([...select.options].map(o=>o.value))!==JSON.stringify(data.profiles.map(p=>p.username))){select.replaceChildren();for(const p of data.profiles){const opt=document.createElement('option');opt.value=p.username;opt.textContent=p.username;select.append(opt)}if(data.profiles.some(p=>p.username===old))select.value=old}accountText();
 const queue=$('publisherQueue');queue.replaceChildren();if(!data.items.length)queue.textContent='No posts queued.';for(const item of data.items){const row=document.createElement('div');row.className='publish-row';const title=document.createElement('strong');title.textContent=item.platform+' ('+item.plan.accounts[item.platform].name+') · '+item.title;const p=document.createElement('p');p.textContent=item.state+' — '+item.message;row.append(title,p);if(item.url){const a=document.createElement('a');a.href=item.url;a.target='_blank';a.rel='noopener';a.textContent='View post';row.append(a)}if(['queued','failed','blocked'].includes(item.state)){const b=document.createElement('button');b.textContent='Cancel';b.onclick=()=>publishAction('/cancel',{id:item.id});row.append(b)}if(['failed','needs_action'].includes(item.state)){const b=document.createElement('button');b.textContent='Retry with same post ID';b.onclick=()=>publishAction('/retry',{id:item.id});row.append(b)}queue.append(row)}
}
async function publishAction(route,data){try{$('publisherError').textContent='';drawPublishing(await publishRequest(route,data))}catch(e){$('publisherError').textContent=e.message}}
async function startAccountSignIn(platform){
 const popup=window.open('about:blank','_blank');if(popup)popup.opener=null;
 try{$('publisherError').textContent='';const result=await publishRequest('/sign-in',{platform});if(popup)popup.location.replace(result.url);else{const link=document.createElement('a');link.href=result.url;link.target='_blank';link.rel='noopener';link.textContent='Continue secure account sign-in';$('publisherError').append(link)}}catch(e){popup?.close();$('publisherError').textContent=e.message}
}
$('signInTikTok').onclick=()=>startAccountSignIn('tiktok');
$('signInYouTube').onclick=()=>startAccountSignIn('youtube');
$('refreshAccounts').onclick=()=>publishAction('/refresh',{});
window.addEventListener('focus',()=>{if(publishSnapshot?.signInReady)publishAction('/refresh',{})});
$('publisherProfile').onchange=accountText;
$('publisherSettings').onsubmit=async e=>{e.preventDefault();await publishAction('/enable',{profile:$('publisherProfile').value,visibility:$('publisherVisibility').value,madeForKids:$('publisherAudience').value==='yes',caption:$('publisherCaption').value,synthetic:$('publisherSynthetic').checked,ownBrand:$('publisherOwnBrand').checked,paidBrand:$('publisherPaidBrand').checked,consent:$('publisherConsent').checked})};
$('publisherPause').onclick=()=>publishAction('/pause',{});
async function refreshPublishing(){try{drawPublishing(await publishRequest(''))}catch{$('publishState').textContent='Publishing needs the running studio server.'}}
refreshPublishing();setInterval(refreshPublishing,5000);
